{
  "id": "SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004",
  "purpose": "Make workspace membership a fail-closed authority so malformed Cargo, npm, pnpm, or uv configuration cannot silently broaden package discovery or a release roster.",
  "scope": "Root membership readers, format-specific absence and invalidity rules, glob compilation, IgnoreWalkLocator propagation, diagnostics, and release-boundary regression tests for Cargo, npm/package.json, pnpm-workspace.yaml, and uv/Python workspaces.",
  "non_goals": [
    "Changing the valid membership or exclusion semantics of Cargo, npm, pnpm, Yarn-compatible package.json workspaces, or uv.",
    "Treating an absent workspace authority file or absent workspace field as malformed when another supported root marker legitimately owns discovery.",
    "Recovering from malformed configuration by scanning more directories.",
    "Changing manifest CST editing or package identity parsing outside discovery."
  ],
  "api_surface": [
    {
      "name": "MembershipAuthority",
      "signature": "pub(crate) enum MembershipAuthority<T> { Absent, Present(T) } returned as Result<MembershipAuthority<T>, LocateError>",
      "description": "A shared semantic result that keeps a genuinely absent authority distinct from a valid authority and represents unreadable, unparseable, invalid-shape, or invalid-glob authority as an error.",
      "error_conditions": [
        "An authority file exists but cannot be read or parsed.",
        "A present members, exclude, workspaces, or packages field has the wrong shape or a non-string item.",
        "A declared membership or exclusion glob is invalid."
      ]
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "Cargo and uv use one shared typed TOML membership reader that returns Absent only when the manifest or relevant workspace table is genuinely absent, Present for a valid table including a deliberately empty members list, and a miette diagnostic error for read failure, TOML parse failure, malformed members/exclude fields, or invalid globs.",
      "is_error_case": true
    },
    {
      "id": "AC-002",
      "criterion": "npm package.json and pnpm-workspace.yaml use the same Absent/Present/error semantics with format-specific parsers. A valid omission of pnpm `packages` follows the explicitly supported pnpm version's documented default and remains authoritative; an unreadable file, invalid or empty YAML document, present wrongly typed packages field, non-string item, or invalid glob fails and never falls through to package.json or admit-all.",
      "is_error_case": true
    },
    {
      "id": "AC-003",
      "criterion": "All read_*_membership functions and glob compilation return Result<MembershipAuthority<_>, LocateError>. IgnoreWalkLocator resolves all selected root authorities before constructing or traversing the walk, returns an error when any authority is invalid, and cannot produce a partial project list. Workspace::load, every planning command, release decision derivation, and execution-time intent revalidation propagate that error before a decision, intent, manifest write, Git mutation, credential read, or provider invocation.",
      "is_error_case": true
    },
    {
      "id": "AC-004",
      "criterion": "Absent authority retains the documented admit-all behavior only for the ecosystem whose authority is truly absent. Present empty membership denies non-root members, exclusions remain effective, hybrid roots retain their current valid behavior, and valid precedence between pnpm and package.json is unchanged.",
      "is_error_case": false
    },
    {
      "id": "AC-005",
      "criterion": "Diagnostics are graph-owned LocateError variants with unique stable codes and identify the ecosystem, safe workspace-relative authority path, invalid field or parser class, source, and remediation without exposing raw file contents. Filesystem parsing errors are not placed in callisto-model or callisto-manifests.",
      "is_error_case": true
    },
    {
      "id": "AC-006",
      "criterion": "Tests replace every current malformed-to-absent assertion with a failure assertion, cover each ecosystem's invalid syntax, wrong field shape, non-string item, and invalid glob, and include an end-to-end release-plan test proving malformed root authority cannot add an otherwise discoverable package to the release decision.",
      "is_error_case": true
    },
    {
      "id": "AC-007",
      "criterion": "All Cargo/uv membership call sites and all npm/pnpm membership call sites migrate in the same change; no second bool, Option, empty-glob, or best-effort parser remains able to encode invalid authority as absence or allow-all.",
      "is_error_case": true
    }
  ],
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY",
  "linked_research": "RESEARCH-RELEASE-MODELS",
  "spec_file_path": "docs/specs/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json",
  "reasoning": "Cargo and uv share an implementation boundary, while npm and pnpm require format-specific parsing and precedence. All four share the semantic result and fail-closed policy; cross-language setup resolution is deliberately not forced into this Rust abstraction."
}
{
  "goal": "Make every workspace membership authority fail closed while preserving valid absence, empty membership, exclusions, hybrid roots, and ecosystem precedence.",
  "architecture": "callisto-graph introduces one graph-private typed authority result shared by Cargo, uv, npm, and pnpm readers, with format-specific parsing and graph-owned diagnostics. Authority is resolved before walking and errors propagate through workspace loading, release planning, intent construction, and revalidation so malformed roots can never silently admit packages.",
  "tech_stack": ["Rust", "toml_edit", "serde_json", "yaml_rust2", "globset", "miette", "just"],
  "tasks": [
    {
      "id": "M-001",
      "title": "Atomically type every authority reader, glob compiler, and immediate locator consumer",
      "files": {
        "modify": ["crates/callisto-graph/src/locate/membership.rs", "crates/callisto-graph/src/locate/ignore_walk.rs", "crates/callisto-graph/src/locate/mod.rs", "crates/callisto-graph/src/error.rs"],
        "test": ["crates/callisto-graph/src/locate/membership.rs", "crates/callisto-graph/src/locate/ignore_walk.rs"]
      },
      "steps": [
        "Add graph-private MembershipAuthority<T> with only Absent and Present(T); in one compilation transaction make build_globset and Cargo, uv, npm/package.json, and pnpm-workspace.yaml readers return Result<MembershipAuthority<_>, LocateError>, with no old infallible adapter.",
        "Return Absent only for a missing authority file or genuinely missing Cargo/uv/npm workspace field; preserve valid empty arrays and hybrid roots as Present. Under the explicitly supported pnpm 12.x semantics, an existing non-empty pnpm-workspace.yaml that omits packages is Present with no child globs: documented behavior is root-only, so unconditional root admission is the sole admitted npm package.",
        "Return graph-owned miette diagnostics for unreadable files, TOML parse failures, malformed members or exclude fields, and invalid globs; include ecosystem, safe relative path, stable code, field/error class, and remediation.",
        "Make glob construction return Result and remove every invalid-entry skip or parse-error-to-absence branch; migrate all four immediate IgnoreWalkLocator consumers to resolve Results before WalkBuilder construction, so signatures compile together and no partial walk is possible.",
        "Add table-driven Cargo/uv/npm/pnpm reader and locator tests for missing, valid empty, included, excluded, hybrid, unreadable, syntax-invalid, wrong-shape, non-string, and invalid-glob authorities; prove pnpm omission admits root but no child, separately from invalid empty or zero-document YAML.",
        "Run `just test`; this batch passes only if all migrated Cargo/uv/npm/pnpm authority and pre-walk locator tests compile and pass, with every malformed authority returning LocateError."
      ],
      "commit_message": "fix(graph): type workspace membership authority",
      "covers_criteria": ["AC-001", "AC-004", "AC-005", "AC-007"]
    },
    {
      "id": "M-002",
      "title": "Propagate authority errors through release boundaries",
      "files": {
        "modify": ["crates/callisto-graph/src/walk.rs", "crates/callisto-graph/src/commands/version.rs", "crates/callisto-graph/src/commands/release_decision.rs", "crates/callisto-graph/src/commands/release.rs", "crates/callisto-cli/src/workspace.rs"],
        "test": ["crates/callisto-graph/src/commands/release_decision.rs", "crates/callisto-cli/tests/durable_release_e2e_tests.rs"]
      },
      "steps": [
        "Inventory Workspace::load, version planning, release-decision derivation, build_release_intent, intent revalidation, and CLI workspace construction; preserve the M-001 locator Result through each path without fallback, logging-and-continuing, or partial lists.",
        "Replace malformed-to-absent assertions with failure assertions for all four ecosystems. Add an end-to-end release-plan fixture where an otherwise discoverable package is below malformed root authority and prove no decision, intent, manifest write, Git mutation, credential read, or provider invocation is constructed.",
        "Add a sibling-gap architecture test that inventories membership-reader and immediate locator call sites and rejects a bool, Option, empty glob, or best-effort parser capable of encoding invalid authority as absence.",
        "Run `just test`; this batch passes only if graph and CLI release-boundary tests prove LocateError stops all release paths before decisions or operations.",
        "Run `just ci`; expect formatting, lint, unit, integration, release-boundary, and sibling-gap tests to pass."
      ],
      "commit_message": "test(graph): propagate authority errors to release boundaries",
      "depends_on": ["M-001"],
      "covers_criteria": ["AC-002", "AC-003", "AC-004", "AC-005", "AC-006", "AC-007"]
    }
  ],
  "batches": [
    {"batch_id": "M-B1", "title": "Atomic typed authority cutover", "target_crate": "callisto-graph", "task_ids": ["M-001"]},
    {"batch_id": "M-B2", "title": "Release-boundary propagation and final gate", "target_crate": "callisto-graph and callisto-cli", "task_ids": ["M-002"]}
  ],
  "linked_spec": "SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004",
  "spec_file_path": "docs/specs/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json",
  "plan_file_path": "docs/projects/SPEC-WORKSPACE-MEMBERSHIP-AUTHORITY-004.json",
  "spec_hash": "sha256:231673ff3cf4c82183670dfd878b04e5e67bd3d89e4aa5e420bcbbd048d10854",
  "linked_requirement": "REQ-DRAFT-RELEASE-RECOVERY"
}

