+    ///
+    /// `Option` is permitted below the reader boundary only for genuinely
+    /// absent files or fields. Every membership reader itself must expose the
+    /// three-state Result<Absent | Present, LocateError> contract, and the
+    /// immediate locator must propagate all three reader Results before a
+    /// walker exists. This prevents a future bool, Option, empty-glob, or
+    /// best-effort adapter from turning malformed authority into admit-all.
+    #[test]
+    fn membership_authority_readers_and_locator_have_no_fallback_encoding() {
+        let membership = include_str!("../locate/membership.rs");
+        let locator = include_str!("../locate/ignore_walk.rs");
+
+        for reader in [
+            "read_membership(",
+            "read_cargo_membership(",
+            "read_python_membership(",
+            "read_package_json_membership(",
+            "read_pnpm_membership(",
+            "read_npm_membership(",
+        ] {
+            let signature = membership
+                .find(&format!("fn {reader}"))
+                .unwrap_or_else(|| panic!("membership reader `{reader}` must remain inventoried"));
+            let source_after_signature = &membership[signature..];
+            let signature_end = source_after_signature
+                .find('{')
+                .unwrap_or_else(|| panic!("membership reader `{reader}` must have a body"));
+            assert!(
+                source_after_signature[..signature_end].contains("Result<MembershipAuthority"),
